    compact.auditMasterReviews = (project?.auditMasterReviews || []).slice(0, 8).map(review => ({ ...compactPlainValue(review, policy), output: "" }));
    compact.researchSessions = [];
    compact.traceLinks = (project?.traceLinks || []).slice(0, 1600).map(link => compactPlainValue(link, policy));
    compact.actionPlanIssues = (project?.actionPlanIssues || []).slice(0, 300).map(item => compactPlainValue(item, policy));
    compact.supportIssues = (project?.supportIssues || []).slice(0, 300).map(item => compactPlainValue(item, policy));
    compact.sourceIssues = (project?.sourceIssues || []).slice(0, 300).map(item => compactPlainValue(item, policy));
    compact.aiReviewImports = (project?.aiReviewImports || []).slice(0, 24).map(item => compactPlainValue(item, policy));
