    const mediaEntries=Object.keys(zip.files).filter(name=>/^word\/media\//i.test(name)&&!zip.files[name].dir).slice(0,240);
    const visualAssets=await Promise.all(mediaEntries.map(async (path,index)=>{ const bytes=await zip.file(path).async("uint8array"); return {id:`DOC-VISUAL-${String(index+1).padStart(4,"0")}`,name:path.split("/").pop()||path,path,mime:imageMimeFromPath(path),size:bytes.byteLength,blob:new Blob([bytes],{type:imageMimeFromPath(path)})}; }));
