      const description = segment.replace(/\s+/g, " ").trim().slice(0, 5000);
      const targets = [...new Set((description.match(/\b(?:SYS|SYSA|SW|HW|SWA|HWA|SWDD|HWDD)[-_]?\d+[A-Z]?\b/ig) || []).map(value => value.toUpperCase()))];
