  function cepEvidencePlaceholder(name, index) {
    const traceability = /^TR \(Traceability Reports\)/.test(name);
    return {
      id: `CEP-BUNDLED-EV-${String(index + 1).padStart(2, "0")}`,
      code: `CEP.${String(index + 1).padStart(3, "0")}`,
      name,
      type: traceability ? "Traceability Report / corroborating" : `${fileType(name)} Document`,
      size: 0,
      chars: 0,
      source: "CEP folder bundled evidence",
      date: "2026-08-27T00:00:00.000Z",
      scope: traceability ? "SYS / SWE traceability" : "待本地解析",
      primaryProcesses: traceability ? ["SYS.2", "SYS.3", "SWE.1", "SWE.2", "SWE.3"] : [],
      content: "",
      tables: [],
      locators: [{ locator: `CEP folder · ${name}`, excerpt: "Bundled CEP source pending local parse." }],
      atomicItems: [],
      helix: summarizeHelixTables([]),
      structure: traceability ? "Traceability report: link observations are corroborating only." : "Bundled CEP source pending local parse.",
      parseStatus: "pending",
      evidenceRole: traceability ? "corroborating" : "index-only",
      bundledCepEvidence: true
    };
  }

  function ensureCepOnlyWorkspace(database) {
    ensureCepXpProject(database);
    const project = (database.standardProjects || []).find(item => item.id === CEP_ONLY_PROJECT_ID);
    if (!project) return;
    const legacyResetRequired = Number(project.cepOnlyWorkspaceVersion || 0) < 3;
    const retained = new Map((project.evidence || []).map(item => [item.name, item]));
    const bundledEvidence = legacyResetRequired
      ? CEP_BUNDLED_EVIDENCE.map((name, index) => cepEvidencePlaceholder(name, index))
      : CEP_BUNDLED_EVIDENCE.map((name, index) => retained.get(name) || cepEvidencePlaceholder(name, index));
    const bundledNames = new Set(CEP_BUNDLED_EVIDENCE);
    const userEvidence = (project.evidence || []).filter(item => !bundledNames.has(item.name));
    project.evidence = [...bundledEvidence, ...userEvidence];
    project.cepOnlyWorkspaceVersion = 4;
    const needsAtomicRecovery = item => {
      const extension = String(item?.name || "").split(".").pop()?.toLowerCase();
      // Legacy OLE DOC is intentionally handled by its sidecar policy. It
      // must not keep the full CEP package in a reparse loop when a sidecar is
      // unavailable, but every structured Office/PDF source must have a real
      // parsed item set before this migration is considered complete.
      if (extension === "doc") return false;
      const parsedItems = Array.isArray(item?.atomicItems) ? item.atomicItems.length : 0;
      return item?.parseStatus !== "parsed" || parsedItems <= 1;
    };
    const needsBundledReparse = legacyResetRequired || project.bundledEvidenceParserVersion !== CEP_BUNDLED_PARSER_VERSION || bundledEvidence.some(item => item.bundledParserVersion !== CEP_BUNDLED_PARSER_VERSION || needsAtomicRecovery(item));
    project.bundledEvidenceImported = !needsBundledReparse && bundledEvidence.every(item => item.parseStatus === "parsed" || item.parseStatus === "failed");
    project.assessmentMode = "standard";
    project.assessments = legacyResetRequired ? [] : (project.assessments || []);
    project.runs = legacyResetRequired ? [] : (project.runs || []);
    project.records = legacyResetRequired ? [] : (project.records || []);
    project.guidelines = legacyResetRequired ? [] : (project.guidelines || []);
    project.actionPlanIssues = [];
    project.wbsIssues = [];
    project.wbsMilestones = [];
    project.workbookImports = [];
    project.sourceIssues = [];
    project.traceabilityIssues = Array.isArray(project.traceabilityIssues) ? project.traceabilityIssues : [];
    project.status = project.assessments.length ? "review" : "ready";
    project.statusLabel = project.assessments.length ? "待复核" : "待本地解析";
    project.assessmentState = project.assessments.length ? "Open" : "Preparation";
    project.progress = project.assessments.length ? Math.max(28, project.progress || 0) : 12;
    project.importSource = {
      importId: `CEP-FOLDER-V${APP_VERSION}`,
      sourceFile: "CEP folder bundled evidence",
      sourceType: "CEP initial local evidence package",
      sourceFiles: [...CEP_BUNDLED_EVIDENCE],
      assessmentBoundary: "Bundled files seed the CEP workspace; additional user-uploaded evidence is allowed and remains subject to assessor classification."
    };
    ensureUniqueAtomicIdentifiers(project);
    project.logs ||= [];
    if (legacyResetRequired) project.logs.unshift({ id: id("log"), date: new Date().toISOString(), action: "Upgrade", user: "AuditFlow", comment: "CEP initial evidence was refreshed; user uploads remain allowed." });
    else if (needsBundledReparse && !project.logs.some(entry => entry.action === "Upgrade" && String(entry.comment || "").includes("v9.2.1"))) project.logs.unshift({ id: id("log"), date: new Date().toISOString(), action: "Upgrade", user: "AuditFlow", comment: "v9.2.1 will reparse the CEP initial files to restore atomic document items after a storage-index recovery." });
    database.standardProjects = Array.isArray(database.standardProjects) ? database.standardProjects : [];
    database.customAudits = Array.isArray(database.customAudits) ? database.customAudits : [];
    database.deletedProjects = Array.isArray(database.deletedProjects) ? database.deletedProjects : [];
    database.activity = [{ icon: "folder", title: "CEP 初始资料已更新", detail: `${CEP_BUNDLED_EVIDENCE.length} 份初始文件可本地解析；追溯报告仅产生佐证观察。`, date: new Date().toISOString() }, ...(database.activity || [])].slice(0, 200);
    database.auditModels ||= [];
    const modelIndex = database.auditModels.findIndex(model => model.id === CEP_YELLOW_DRAFT_MODEL.id);
    if (modelIndex >= 0) Object.assign(database.auditModels[modelIndex], CEP_YELLOW_DRAFT_MODEL);
    else database.auditModels.unshift({ ...CEP_YELLOW_DRAFT_MODEL });
    database.settings ||= {};
    database.settings.engineVersion = APP_VERSION;
    database.settings.helpVersion = `v${APP_VERSION}`;
    database.settings.releaseVersion = APP_VERSION;
    database.settings.translationLayerVersion = 3;
    database.settings.reviewEditMode = "optimistic-local";
    database.settings.cepOnlyWorkspaceVersion = 4;
    database.settings.cepBundledParserVersion = CEP_BUNDLED_PARSER_VERSION;
    database.settings.yellowDraftScoringModel = CEP_YELLOW_DRAFT_MODEL.id;
  }

