  document.addEventListener("keydown",event=>{const key=typeof event.key==="string"?event.key.toLowerCase():"";const target=event.target;if((event.metaKey||event.ctrlKey)&&key==="k"){event.preventDefault();openGlobalSearchModal();}if(target?.id==="globalSearchInput"&&event.key==="Enter"){event.preventDefault();const q=target.value?.trim();if(q)globalSearch(q);}if(event.key==="Escape"){closeModal();closeDrawer();document.getElementById("sidebar").classList.remove("open");}const shortcut={s:"strength",w:"weakness",r:"recommendation",o:"observation",c:"comment",q:"question"}[key];if(shortcut&&!event.metaKey&&!event.ctrlKey&&!event.altKey&&!target?.matches?.("input,textarea,select")&&!modalRoot.children.length&&!drawerRoot.children.length){const route=parseRoute();if(route[0]==="standard"&&route[1]&&route[1]!=="report"&&["grid","list"].includes(ui.projectTab)){const p=db.standardProjects.find(x=>x.id===route[1]);if(p){event.preventDefault();recordModal(p,null,ui.activeIndicator);setTimeout(()=>{const select=document.querySelector("#recordForm [name=type]");if(select)select.value=shortcut;},0);}}}});
